# 1. for...else 用法
for n in range(2, 10):
    for x in range(2, n):
        if n % x == 0:
            break
    else:
        print(f"{n} is prime")

# 2. *args 和 **kwargs

def log(level, *messages, **meta):
    for msg in messages:
        print(f"[{level}] {msg}")
    for k, v in meta.items():
        print(f"  {k}: {v}")

log("INFO", "start", "end", user="alice", duration=42)

