# 4. 参数解包
def point(x, y): return {"x": x, "y": y}
p = [3, 5]
print(point(*p))          # {"x": 3, "y": 5}

d = {"x": 10, "y": 20}
print(point(**d))         # {"x": 10, "y": 20}
